import sys
import bisect

def main():
    import sys
    import bisect

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m, d = readints()
    physics_cups = [readints() for _ in range(n)]
    informatics_cups = [readints() for _ in range(m)]

    physics_cups.sort(key=lambda x: (-x[0], x[1]))
    informatics_cups.sort(key=lambda x: (-x[0], x[1]))

    max_significance = 0

    # Precompute the maximum significance for each prefix of physics cups
    physics_prefix_sum = [0] * (n + 1)
    current_width = 0
    for i in range(n):
        if current_width + physics_cups[i][1] <= d:
            current_width += physics_cups[i][1]
            physics_prefix_sum[i + 1] = physics_prefix_sum[i] + physics_cups[i][0]
        else:
            break

    # Precompute the maximum significance for each suffix of informatics cups
    informatics_suffix_sum = [0] * (m + 1)
    current_width = 0
    for i in range(m - 1, -1, -1):
        if current_width + informatics_cups[i][1] <= d:
            current_width += informatics_cups[i][1]
            informatics_suffix_sum[i] = informatics_suffix_sum[i + 1] + informatics_cups[i][0]
        else:
            break

    # Binary search to find the best combination
    for i in range(n):
        if physics_prefix_sum[i] == 0:
            continue
        remaining_width = d - physics_prefix_sum[i]
        j = bisect.bisect_left(informatics_suffix_sum, 0, key=lambda x: x if x <= remaining_width else float('inf'))
        if j < m and informatics_suffix_sum[j] <= remaining_width:
            max_significance = max(max_significance, physics_prefix_sum[i] + informatics_suffix_sum[j])

    print(max_significance)

if __name__ == "__main__":
    main()
